// ASTrust runtime: the language-independent pieces shared by samples —
// Merkle-hash primitives, the specializer's output context, and the code store
// (Rust source of specialized dispatchers → rustc → cdylib → dlopen/dlsym).
//
// A sample includes this file as a module (`#[path = ".../runtime/astrust.rs"] pub mod astrust;`)
// and the code generated by lib/astrustgen.rb refers to it.
#![allow(dead_code)]
#[path = "astrust_loader.rs"]
pub mod loader;
use std::collections::{HashMap, HashSet};
use std::ffi::{CStr, CString};
use std::os::raw::{c_char, c_int, c_void};
use std::path::{Path, PathBuf};

// ---- hashing (FNV-1a based, stable across processes and builds) ------------

#[inline]
pub fn hash_bytes(b: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf29ce484222325;
    for &x in b { h = (h ^ x as u64).wrapping_mul(0x100000001b3); }
    h
}
#[inline] pub fn hash_str(s: &str) -> u64 { hash_bytes(s.as_bytes()) }
#[inline]
pub fn hash_u64(v: u64) -> u64 {
    let mut h = v.wrapping_mul(0x9e3779b97f4a7c15);
    h ^= h >> 29; h = h.wrapping_mul(0xbf58476d1ce4e5b9); h ^= h >> 32;
    h
}
#[inline]
pub fn hash_merge(h: u64, v: u64) -> u64 {
    (h.rotate_left(5) ^ v).wrapping_mul(0x100000001b3).wrapping_add(0x9e3779b9)
}

// ---- specializer context ------------------------------------------------------

/// Accumulates the Rust source of specialized dispatchers.  Each item (an SD type
/// `T_<hash>`, a list type `L_<hash>`, an exported entry `SD_<hash>`) is emitted once.
pub struct SpecCtx {
    pub out: String,
    pub emitted: HashSet<String>,
    pub open: HashSet<u64>,       // hashes of the nodes being specialized now (ancestors)
    pub spec_depth: u32,          // nesting of speculated callees
    pub spec_max_depth: u32,
    pub comments: bool,
    pub rec: Vec<usize>,          // nodes a direct recursive call (R_<hash>) names; their S_<hash> is owed
    pub unrolled: HashSet<u64>,   // recursion targets being compiled into themselves (their copy's sites: R_)
    pub rec_unroll: bool,         // ASTRUST_REC_UNROLL=0: a recursive site never compiles its target in
    pub reenter: u32,             // inside such a copy: nodes being specialized are specialized again
    pub holes: Vec<(usize, usize)>, // bound operands (@hole) the entry being specialized reads: (address, size)
    pub patch: bool,              // emitting the patch-binding crate (patch.o): holes become symbols
    patch_root: usize,            // the entry whose own tree is being specialized (0: none)
    patch_hash: u64,
}

impl SpecCtx {
    pub fn new() -> Self {
        SpecCtx { out: String::new(), emitted: HashSet::new(), open: HashSet::new(), spec_depth: 0,
                  // ASTRUST_SPEC_DEPTH=n: how deep speculated callees nest (0: no speculation)
                  spec_max_depth: std::env::var("ASTRUST_SPEC_DEPTH").ok().and_then(|v| v.parse().ok()).unwrap_or(2), comments: std::env::var_os("ASTRUST_SD_COMMENTS").is_some(), rec: vec![],
                  unrolled: HashSet::new(), rec_unroll: std::env::var("ASTRUST_REC_UNROLL").map_or(true, |v| v != "0"), reenter: 0, holes: vec![],
                  patch: false, patch_root: 0, patch_hash: 0 }
    }
    /// The entry `root` (0: done) whose tree is specialized next; in the patch crate its holes are bound.
    pub fn begin_entry(&mut self, root: usize, hash: u64) {
        // ASTRUST_PATCH_HOLES=0: the patch crate reads holes from the node too (a control for the loader alone)
        let on = self.patch && std::env::var("ASTRUST_PATCH_HOLES").map_or(true, |v| v != "0");
        self.patch_root = if on { root } else { 0 };
        self.patch_hash = hash;
    }
    fn bound(&self) -> bool { self.patch_root != 0 && self.spec_depth == 0 }
    /// An item's name in a bound tree carries its offset from the root: its holes are the root's.
    pub fn positional(&self, name: String, at: usize) -> String {
        if self.bound() { format!("{}P{}", name, at.wrapping_sub(self.patch_root)) } else { name }
    }
    /// The symbol standing for hole `op` at address `at`, declared once with the embedder's `item`
    /// (impls of H_<symbol>, %SYM% the symbol) (None: read it from the node).
    pub fn hole_sym(&mut self, op: &str, at: usize, item: &str) -> Option<String> {
        // a hole at the root itself stays: its address is the entry's `n`, already in a register
        if !self.bound() || at == self.patch_root { return None; }
        let s = format!("ASTRUST_HOLE_{}_{}", op, at - self.patch_root);
        if self.emitted.insert(s.clone()) {
            self.out.push_str(&format!("pub struct H_{0};\nextern \"C\" {{ pub static {0}: u8; }}\n{1}\n", s, item.replace("%SYM%", &s)));
        }
        Some(s)
    }
    /// "P" for a call to the bound entry itself (R_<hash>P checks the node against ASTRUST_ROOT).
    pub fn rec_suffix(&self, h: u64) -> &'static str { if self.patch_root != 0 && h == self.patch_hash { "P" } else { "" } }
}

// ---- code store ----------------------------------------------------------------

extern "C" {
    fn dlopen(file: *const c_char, mode: c_int) -> *mut c_void;
    fn dlsym(h: *mut c_void, sym: *const c_char) -> *mut c_void;
    fn dlerror() -> *const c_char;
}
const RTLD_NOW: c_int = 2;
fn verbose() -> bool { std::env::var_os("ASTRUST_VERBOSE").is_some() }
const RTLD_GLOBAL: c_int = 0x100;

/// How to build a code store: the embedder's crate (a Rust dylib) that SD code links against.
pub struct BakeConfig {
    pub crate_name: String,
    pub crate_path: PathBuf,      // the embedder's lib<name>.so (its metadata is embedded)
    pub lib_dirs: Vec<PathBuf>,
    pub rpaths: Vec<PathBuf>,
    pub prelude: String,          // `use` lines etc. at the top of the SD crate
    pub build_id: String,
    pub verbose: bool,
}

/// A directory holding specialized code: `items/<name>.rs` (one per emitted item,
/// content-addressed by its hash name, so bakes accumulate) and the linked `all.so`.
pub struct CodeStore {
    pub dir: PathBuf,
    handle: *mut c_void,
}

impl CodeStore {
    pub fn new(dir: impl AsRef<Path>) -> Self { CodeStore { dir: dir.as_ref().to_path_buf(), handle: std::ptr::null_mut() } }

    /// dlopen `all.so` if present and baked against the same build.
    pub fn load(&mut self, build_id: &str) -> bool {
        let so = self.dir.join("all.so");
        if !so.exists() { return false; }
        let cs = CString::new(so.to_string_lossy().as_bytes()).unwrap();
        let h = unsafe { dlopen(cs.as_ptr(), RTLD_NOW | RTLD_GLOBAL) };
        if h.is_null() {
            let e = unsafe { CStr::from_ptr(dlerror()) };
            if verbose() { eprintln!("astrust: cannot load {}: {}", so.display(), e.to_string_lossy()); }
            return false;
        }
        let idp = unsafe { dlsym(h, b"ASTRUST_BUILD_ID\0".as_ptr() as *const c_char) } as *const [u8; 16];
        if idp.is_null() || unsafe { &*idp }[..] != build_id.as_bytes()[..16.min(build_id.len())] {
            if verbose() { eprintln!("astrust: {} was baked against another build; ignored", so.display()); }
            return false;
        }
        self.handle = h;
        true
    }

    pub fn loaded(&self) -> bool { !self.handle.is_null() }

    /// Address of the exported entry `SD_<hash>`, if baked.
    pub fn lookup(&self, hash: u64) -> Option<*const c_void> {
        if self.handle.is_null() { return None; }
        let name = CString::new(format!("SD_{:016x}", hash)).unwrap();
        let p = unsafe { dlsym(self.handle, name.as_ptr()) };
        if p.is_null() { None } else { Some(p as *const c_void) }
    }

    /// Split the specializer output into items and store each under its name in `sub` (items/, pitems/).
    pub fn add_items_in(&self, sub: &str, src: &str) -> std::io::Result<usize> {
        let items = self.dir.join(sub);
        std::fs::create_dir_all(&items)?;
        let mut added = 0;
        for (name, text) in split_items(src) {
            let p = items.join(format!("{}.rs", name));
            if !p.exists() { std::fs::write(&p, text)?; added += 1; }
        }
        Ok(added)
    }
    pub fn add_items(&self, src: &str) -> std::io::Result<usize> { self.add_items_in("items", src) }

    /// Path of the patch-binding object (the same SDs as `all.so`, holes as symbols), if baked.
    pub fn patch_obj(&self) -> Option<PathBuf> {
        let p = self.dir.join("patch.o");
        if self.loaded() && p.exists() { Some(p) } else { None }
    }

    /// Concatenate the stored items of `sub` into one crate and start rustc on it.
    fn rustc(&self, cfg: &BakeConfig, sub: &str, patch: bool) -> Result<(std::process::Child, PathBuf, PathBuf), String> {
        let items = self.dir.join(sub);
        let mut names: Vec<PathBuf> = std::fs::read_dir(&items).map_err(|e| e.to_string())?
            .filter_map(|e| e.ok().map(|e| e.path())).collect();
        names.sort();
        let mut src = String::new();
        src.push_str("// Auto-generated by the ASTrust code store. Do not edit.\n");
        src.push_str("#![allow(non_camel_case_types, non_snake_case, non_upper_case_globals, unused_unsafe, unused_variables, unused_mut, unused_parens, unused_imports, unreachable_code, dead_code)]\n");
        src.push_str(&cfg.prelude);
        // the bound node, for a recursive call to check that it reenters the same node (R_<hash>P)
        if patch { src.push_str("extern \"C\" { static ASTRUST_ROOT: u8; }\n"); }
        let mut idb = [b'0'; 16];
        for (i, b) in cfg.build_id.bytes().take(16).enumerate() { idb[i] = b; }
        src.push_str(&format!("#[no_mangle]\npub static ASTRUST_BUILD_ID: [u8; 16] = *b\"{}\";\n", String::from_utf8_lossy(&idb)));
        for p in &names { src.push_str(&std::fs::read_to_string(p).map_err(|e| e.to_string())?); }
        let (rs, out) = if patch { ("patch.rs", "patch.o") } else { ("all.rs", "all.so") };
        let rs = self.dir.join(rs);
        std::fs::write(&rs, &src).map_err(|e| e.to_string())?;
        let tmp = self.dir.join(format!("{}.tmp{}", out, std::process::id()));
        let mut cmd = std::process::Command::new(std::env::var("ASTRUST_RUSTC").unwrap_or_else(|_| "rustc".into()));
        cmd.args(["--edition", "2021", "--crate-type", "cdylib", "--crate-name", "astrust_sd"])
            .args(["-C", "prefer-dynamic", "-C", "debuginfo=0"]);
        let opts = std::env::var("ASTRUST_BUILD_OPTS").unwrap_or_else(|_| "-C opt-level=3 -C target-cpu=native -C codegen-units=8".into());
        let mut opts: Vec<&str> = opts.split_whitespace().collect();
        if patch {
            // one object: rustc emits one only with one codegen unit.  PIC as all.so: a hole is reached
            // through the GOT, which the loader relaxes to an immediate (the static model would need
            // libsaruby's data in the low 2 GB: it takes their addresses as 32-bit immediates)
            while let Some(i) = (1..opts.len()).find(|&i| opts[i].starts_with("codegen-units=") && opts[i - 1] == "-C") { opts.drain(i - 1..=i); }
            cmd.args(["--emit=obj", "-C", "codegen-units=1"]);
        }
        cmd.args(opts);
        cmd.arg("--extern").arg(format!("{}={}", cfg.crate_name, cfg.crate_path.display()));
        for d in &cfg.lib_dirs { cmd.arg("-L").arg(d); }
        let rp: Vec<String> = cfg.rpaths.iter().map(|p| p.display().to_string()).collect();
        if !rp.is_empty() && !patch { cmd.arg("-C").arg(format!("link-args=-Wl,-rpath,{}", rp.join(":"))); }
        cmd.arg(&rs).arg("-o").arg(&tmp);
        cmd.stdout(std::process::Stdio::null()).stderr(std::process::Stdio::piped());
        if cfg.verbose { eprintln!("astrust: {:?}", cmd); }
        let child = cmd.spawn().map_err(|e| format!("rustc: {}", e))?;
        Ok((child, tmp, self.dir.join(out)))
    }

    /// Build `all.so` from items/ and, when pitems/ exists, `patch.o` from it (two rustc in parallel).
    pub fn build(&self, cfg: &BakeConfig) -> Result<(), String> {
        let mut jobs = vec![self.rustc(cfg, "items", false)?];
        if self.dir.join("pitems").is_dir() { jobs.push(self.rustc(cfg, "pitems", true)?); }
        let mut err = None;
        for (i, (child, tmp, out)) in jobs.into_iter().enumerate() {
            let o = child.wait_with_output().map_err(|e| format!("rustc: {}", e))?;
            if o.status.success() { std::fs::rename(&tmp, &out).map_err(|e| e.to_string())?; continue; }
            let _ = std::fs::remove_file(&tmp);
            let msg = String::from_utf8_lossy(&o.stderr).into_owned();
            // without patch.o every body keeps the shared SD of all.so
            if i == 1 { let _ = std::fs::remove_file(&out); eprintln!("astrust: patch.o not built:\n{}", msg); } else { err = Some(msg); }
        }
        err.map_or(Ok(()), Err)
    }
}

/// Items begin at a line `pub struct <NAME>;` or `#[no_mangle]` (followed by `pub fn <NAME>(`).
fn split_items(src: &str) -> Vec<(String, String)> {
    let mut out: Vec<(String, String)> = vec![];
    let mut cur: Option<(String, String)> = None;
    let mut lines = src.lines().peekable();
    while let Some(l) = lines.next() {
        let start = if let Some(r) = l.strip_prefix("pub struct ") {
            Some(r.trim_end_matches(';').to_string())
        } else if l == "#[no_mangle]" {
            lines.peek().and_then(|n| n.strip_prefix("pub fn ")).map(|r| r.split('(').next().unwrap().to_string())
        } else { None };
        if let Some(name) = start {
            if let Some(c) = cur.take() { out.push(c); }
            cur = Some((name, String::new()));
        }
        if let Some(c) = cur.as_mut() { c.1.push_str(l); c.1.push('\n'); }
    }
    if let Some(c) = cur.take() { out.push(c); }
    out
}

// ---- two-tier store: shared preload (built once, next to the binary) + per-program --------

/// Entry bookkeeping for AOT: bodies of the embedder's prelude go to a shared
/// `preload` store (baked once per build), everything else to the program store.
/// `register` swaps a body's dispatcher when a baked SD exists; `bake` writes both.
pub struct TieredStore {
    pub preload_dir: PathBuf,
    pub program: Option<CodeStore>,
    preload: Option<CodeStore>,
    preload_tried: bool,
    pub collect: bool,
    pub prelude_entries: Vec<usize>,
    pub program_entries: Vec<usize>,
    pub hits: usize,
    /// Patch binding: a body's own copy from patch.o, made at its first dispatch (`defer` / `bind`).
    pub patch: bool,
    loader: Option<loader::Loader>,
    pending: HashMap<usize, (usize, u64, bool)>,   // node -> (shared SD, hash, is_prelude)
}

impl TieredStore {
    pub fn new(preload_dir: PathBuf, program_dir: Option<PathBuf>, build_id: &str, collect: bool) -> Self {
        let program = program_dir.map(|d| { let mut cs = CodeStore::new(d); cs.load(build_id); cs });
        TieredStore { preload_dir, program, preload: None, preload_tried: false, collect, prelude_entries: vec![], program_entries: vec![], hits: 0,
                      patch: false, loader: None, pending: HashMap::new() }
    }
    /// After `register` found `shared` for `node`: true if the body is to get its own copy at its first
    /// dispatch (the embedder then installs a trampoline that calls `bind`).
    pub fn defer(&mut self, node: usize, hash: u64, is_prelude: bool, shared: *const c_void) -> bool {
        if !self.patch || !loader::SUPPORTED { return false; }
        let cs = if is_prelude { self.preload.as_ref() } else { self.program.as_ref() };
        if cs.and_then(|cs| cs.patch_obj()).is_none() { return false; }
        self.pending.insert(node, (shared as usize, hash, is_prelude));
        true
    }
    /// The dispatcher for a deferred node: its bound copy, else (any failure) the shared SD.
    /// `near`: an address in the embedder's library (the copies call it with rel32).
    pub fn bind(&mut self, node: usize, build_id: &str, near: usize, hole: loader::HoleFn) -> Option<*const c_void> {
        let (shared, hash, is_prelude) = self.pending.remove(&node)?;
        let cs = if is_prelude { self.preload.as_ref() } else { self.program.as_ref() };
        let path = cs.and_then(|cs| cs.patch_obj())?;
        let ld = self.loader.get_or_insert_with(|| loader::Loader::new(near));
        match ld.instantiate(&path, build_id, hash, node, hole) {
            Ok(p) => Some(p as *const c_void),
            Err(e) => {
                if verbose() { eprintln!("astrust: SD_{:016x} not bound: {}", hash, e); }
                Some(shared as *const c_void)
            }
        }
    }
    /// (copies made, failures, bytes of the copies)
    pub fn patch_stats(&self) -> (usize, usize, usize) { self.loader.as_ref().map_or((0, 0, 0), |l| (l.instances, l.failed, l.bytes)) }
    fn preload(&mut self, build_id: &str) -> Option<&CodeStore> {
        if !self.preload_tried {
            self.preload_tried = true;
            let mut cs = CodeStore::new(&self.preload_dir);
            if cs.load(build_id) { self.preload = Some(cs); }
        }
        self.preload.as_ref()
    }
    /// Record an entry (a node, as usize) and return the SD address to install, if baked.
    pub fn register(&mut self, node: usize, hash: u64, is_prelude: bool, build_id: &str) -> Option<*const c_void> {
        if self.program.is_none() { return None; }   // --plain
        if self.collect { if is_prelude { self.prelude_entries.push(node) } else { self.program_entries.push(node) } }
        let p = if is_prelude { self.preload(build_id).and_then(|cs| cs.lookup(hash)) }
                else { self.program.as_ref().and_then(|cs| cs.lookup(hash)) };
        if p.is_some() { self.hits += 1; }
        p
    }
    /// Bake: `spec(entries, patch)` returns the specializer output for a set of entries (patch: for patch.o,
    /// built next to all.so where the loader runs).
    pub fn bake(&mut self, program_dir: &Path, cfg: &BakeConfig, spec: impl Fn(&[usize], bool) -> String) -> Result<usize, String> {
        if self.preload(&cfg.build_id).is_none() {
            let _ = std::fs::remove_dir_all(self.preload_dir.join("items"));
            let _ = std::fs::remove_dir_all(self.preload_dir.join("pitems"));
            Self::bake_into(&self.preload_dir, &self.prelude_entries, &spec, cfg)?;
        }
        Self::bake_into(program_dir, &self.program_entries, &spec, cfg)
    }
    fn bake_into(dir: &Path, entries: &[usize], spec: &impl Fn(&[usize], bool) -> String, cfg: &BakeConfig) -> Result<usize, String> {
        std::fs::create_dir_all(dir).map_err(|e| e.to_string())?;
        let cs = CodeStore::new(dir);
        let added = cs.add_items(&spec(entries, false)).map_err(|e| e.to_string())?;
        let padded = if loader::SUPPORTED { cs.add_items_in("pitems", &spec(entries, true)).map_err(|e| e.to_string())? } else { 0 };
        if added + padded > 0 || !dir.join("all.so").exists() || (loader::SUPPORTED && !dir.join("patch.o").exists()) { cs.build(cfg)?; }
        Ok(added)
    }
}
